package main

// Fixture files of catalog provider simulations: deterministic audio the
// server embeds and serves publicly, so a simulated provider can hand an app
// a recording URL (fixture_url in a mock expression) and play caller audio
// into a simulated media stream. The files are generated by
// TestIntegrationMockFixturesAreCurrent; rerun it with UPDATE_MOCK_FIXTURES=1
// to rewrite them.

import (
	"bytes"
	"embed"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"fmt"
	"io/fs"
	"net/http"
	"path"
	"strings"
	"sync"
	"time"
)

//go:embed integration-mock-fixtures/*.wav
var integrationMockFixtureFS embed.FS

const integrationMockFixtureDir = "integration-mock-fixtures"

// Caller audio fixtures can play into a media stream; the recordings are
// for recording download URLs only.
var mockCallerAudioFixtures = map[string]bool{"caller-speech-8k.wav": true}

var mockFixtureModTime = time.Date(2026, 11, 21, 0, 0, 0, 0, time.UTC)

type mockFixture struct {
	name        string
	data        []byte
	contentType string
}

func mockFixtureByName(name string) (*mockFixture, bool) {
	if name == "" || strings.ContainsAny(name, "/\\") || name != path.Clean(name) || strings.HasPrefix(name, ".") {
		return nil, false
	}
	data, err := fs.ReadFile(integrationMockFixtureFS, integrationMockFixtureDir+"/"+name)
	if err != nil {
		return nil, false
	}
	contentType := "application/octet-stream"
	if strings.HasSuffix(name, ".wav") {
		contentType = "audio/wav"
	}
	return &mockFixture{name: name, data: data, contentType: contentType}, true
}

// mockMaxInlineFixture bounds a fixture inlined into a hand-off with
// fixture_base64, so the hand-off stays well under the SDK's 1 MiB request
// limit.
const mockMaxInlineFixture = 512 << 10

// mockFixtureBase64 is a fixture file's bytes, base64-encoded, for apps that
// should not fetch fixture_url (an app inside an Environment reaches the
// network only through the environment's edge).
func mockFixtureBase64(name string) (string, error) {
	fixture, ok := mockFixtureByName(name)
	if !ok {
		return "", fmt.Errorf("fixture_base64: unknown fixture %q", name)
	}
	if len(fixture.data) > mockMaxInlineFixture {
		return "", fmt.Errorf("fixture_base64: fixture %q is %d bytes, over the %d byte inline limit", name, len(fixture.data), mockMaxInlineFixture)
	}
	return base64.StdEncoding.EncodeToString(fixture.data), nil
}

// mockAudioFixtureKnown reports whether name can be played as caller audio.
func mockAudioFixtureKnown(name string) bool {
	if name == mockCallerSilence {
		return true
	}
	if !mockCallerAudioFixtures[name] {
		return false
	}
	_, ok := mockFixtureByName(name)
	return ok
}

var mockCallerSampleCache sync.Map // "name@rate" -> []int16

// mockCallerSamples is a caller fixture's audio at rate Hz, mono.
func mockCallerSamples(name string, rate int) ([]int16, error) {
	key := fmt.Sprintf("%s@%d", name, rate)
	if cached, ok := mockCallerSampleCache.Load(key); ok {
		return cached.([]int16), nil
	}
	fixture, ok := mockFixtureByName(name)
	if !ok || !mockCallerAudioFixtures[name] {
		return nil, fmt.Errorf("caller audio %q is not a fixture", name)
	}
	wav, err := mockReadWAV(fixture.data)
	if err != nil {
		return nil, fmt.Errorf("fixture %s: %w", name, err)
	}
	samples := mockResample(wav.mono(), wav.rate, rate)
	mockCallerSampleCache.Store(key, samples)
	return samples, nil
}

// mockResample converts by linear interpolation; fixtures are speech-band
// audio, so no anti-alias filter is needed for these rates.
func mockResample(in []int16, from, to int) []int16 {
	if from == to || len(in) == 0 {
		return append([]int16(nil), in...)
	}
	n := int(int64(len(in)) * int64(to) / int64(from))
	out := make([]int16, n)
	for i := range out {
		pos := int64(i) * int64(from)
		idx := int(pos / int64(to))
		frac := float64(pos%int64(to)) / float64(to)
		a := float64(in[idx])
		b := a
		if idx+1 < len(in) {
			b = float64(in[idx+1])
		}
		out[i] = int16(a + (b-a)*frac)
	}
	return out
}

// --- WAV ---

type mockWAV struct {
	rate     int
	channels int
	samples  []int16 // interleaved
}

func (w mockWAV) mono() []int16 {
	if w.channels == 1 {
		return w.samples
	}
	out := make([]int16, len(w.samples)/w.channels)
	for i := range out {
		sum := 0
		for c := 0; c < w.channels; c++ {
			sum += int(w.samples[i*w.channels+c])
		}
		out[i] = int16(sum / w.channels)
	}
	return out
}

func mockReadWAV(data []byte) (mockWAV, error) {
	var out mockWAV
	if len(data) < 12 || string(data[0:4]) != "RIFF" || string(data[8:12]) != "WAVE" {
		return out, errors.New("not a RIFF/WAVE file")
	}
	bits := 0
	for pos := 12; pos+8 <= len(data); {
		id := string(data[pos : pos+4])
		size := int(binary.LittleEndian.Uint32(data[pos+4 : pos+8]))
		body := pos + 8
		if size < 0 || body+size > len(data) {
			return out, errors.New("truncated chunk")
		}
		switch id {
		case "fmt ":
			if size < 16 {
				return out, errors.New("short fmt chunk")
			}
			if format := binary.LittleEndian.Uint16(data[body:]); format != 1 {
				return out, fmt.Errorf("format %d is not PCM", format)
			}
			out.channels = int(binary.LittleEndian.Uint16(data[body+2:]))
			out.rate = int(binary.LittleEndian.Uint32(data[body+4:]))
			bits = int(binary.LittleEndian.Uint16(data[body+14:]))
		case "data":
			if bits != 16 || out.channels < 1 || out.rate < 1 {
				return out, errors.New("only 16-bit PCM is supported")
			}
			raw := data[body : body+size-size%2]
			out.samples = make([]int16, len(raw)/2)
			for i := range out.samples {
				out.samples[i] = int16(binary.LittleEndian.Uint16(raw[2*i:]))
			}
			return out, nil
		}
		pos = body + size + size%2
	}
	return out, errors.New("no data chunk")
}

func mockWriteWAV(w mockWAV) []byte {
	var buf bytes.Buffer
	dataSize := 2 * len(w.samples)
	buf.WriteString("RIFF")
	_ = binary.Write(&buf, binary.LittleEndian, uint32(36+dataSize))
	buf.WriteString("WAVEfmt ")
	_ = binary.Write(&buf, binary.LittleEndian, uint32(16))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(1))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(w.channels))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(w.rate))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(w.rate*w.channels*2))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(w.channels*2))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(16))
	buf.WriteString("data")
	_ = binary.Write(&buf, binary.LittleEndian, uint32(dataSize))
	_ = binary.Write(&buf, binary.LittleEndian, w.samples)
	return buf.Bytes()
}

// --- serving ---

// handleIntegrationSimulationFixture serves the fixture files publicly: a
// simulated provider hands these URLs to apps exactly as a provider hands
// out recording links, and they hold no data of any runtime.
func (s *Server) handleIntegrationSimulationFixture(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		w.Header().Set("Allow", "GET, HEAD")
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	name := strings.TrimPrefix(r.URL.Path, "/api/integration-simulation/fixtures/")
	name = strings.TrimPrefix(name, "/integration-simulation/fixtures/")
	fixture, ok := mockFixtureByName(name)
	if !ok {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", fixture.contentType)
	w.Header().Set("Cache-Control", "public, max-age=86400")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	http.ServeContent(w, r, fixture.name, mockFixtureModTime, bytes.NewReader(fixture.data))
}
